// MEGA Cloud Storage connector, in-app explorer, backups and best-effort single-writer sync.
const CLOUD_ROOT_NAME='chicCanva Cloud',CLOUD_BACKUP_NAME='.backups',CLOUD_SYNC_NAME='.synch',CLOUD_SECRET_DB='chicCanva-cloud-secrets',CLOUD_SECRET_STORE='secrets',CLOUD_META_KEY='chicCanva.cloud.meta.v1',CLOUD_LOG_KEY='chicCanva.cloud.run-log.v1',CLOUD_UPLOAD_INTERVAL=10*60*1000,CLOUD_SETTLE_DELAY=30*1000,CLOUD_LEASE_MS=90*1000;
let cloudStorage=null,cloudRoot=null,cloudCurrent=null,cloudPath=[],cloudSelection=new Set(),cloudEditMode=false,cloudExplorerMode='browse',cloudPendingArtifact=null,cloudPreviewUrl='',cloudDestinationResolver=null,cloudTextResolver=null,cloudConfirmResolver=null,cloudDeleteModeResolver=null,cloudMoveTarget=null,cloudBackupTimer=0,cloudSyncPoll=0,cloudSyncBusy=false,cloudLocalDirty=false,cloudLastPayloadHash='',cloudStartupSnapshot=null,cloudConflictSnapshot=null;
let cloudMeta=readCloudMeta();
let cloudTooltipHome=null,cloudPreviewGeneration=0;
let cloudAutosaveBusy=false,cloudPendingSnapshot=null,cloudQueuedAt=0;
