let cloudCopyEntries=[],cloudSelectedCopy=null,cloudSelectedCopySnapshot=null;

function readCloudMeta(){const defaults={backupInstanceId:uid('backup'),syncSessionId:uid('sync'),writerId:uid('writer'),lastRevision:0,lastBackupAt:0,lastSyncAt:0,lastSyncHash:'',syncSuspended:false};try{return{...defaults,...JSON.parse(localStorage.getItem(CLOUD_META_KEY)||'{}')}}catch(error){return defaults}}
function writeCloudMeta(){try{localStorage.setItem(CLOUD_META_KEY,JSON.stringify(cloudMeta))}catch(error){}}
function readCloudRunLogs(){try{const value=JSON.parse(localStorage.getItem(CLOUD_LOG_KEY)||'[]');return Array.isArray(value)?value.filter(item=>item&&['backup','sync'].includes(item.kind)&&Number.isFinite(Number(item.at))).slice(-100):[]}catch(error){return[]}}
function writeCloudRunLogs(){try{localStorage.setItem(CLOUD_LOG_KEY,JSON.stringify(cloudRunLogs.slice(-100)))}catch(error){}}
function cloudRunOutcomeText(outcome){return t({running:'Operazione avviata',success:'Operazione completata',unchanged:'Nessuna modifica da caricare',conflict:'Sessione più recente rilevata: sincronizzazione sospesa',suspended:'Sincronizzazione sospesa',busy:'Operazione già in corso',failed:'Operazione non riuscita'}[outcome]||'Stato non disponibile')}
function appendCloudRunLog(kind,outcome,{source='automatic',detail=''}={}){const entry={id:uid('cloudrun'),at:Date.now(),kind,outcome,source,detail:String(detail||'').slice(0,500)};cloudRunLogs.push(entry);cloudRunLogs=cloudRunLogs.slice(-100);writeCloudRunLogs();syncCloudRunUi();if($('cloudRunLogDialog')?.open&&cloudVisibleLogKind===kind)renderCloudRunLog(kind);return entry}
function finishCloudRunLog(entry,outcome,detail=''){if(!entry)return;entry.outcome=outcome;entry.detail=String(detail||'').slice(0,500);writeCloudRunLogs();syncCloudRunUi();if($('cloudRunLogDialog')?.open&&cloudVisibleLogKind===entry.kind)renderCloudRunLog(entry.kind)}
function latestCloudRun(kind){return[...cloudRunLogs].reverse().find(item=>item.kind===kind)}
function cloudRunStatusText(kind){if(cloudQueuedAt&&((kind==='backup'&&preferences.cloudBackup)||(kind==='sync'&&preferences.cloudSync&&!cloudMeta.syncSuspended)))return t('In coda fino alle')+' '+new Date(cloudQueuedAt).toLocaleTimeString(appLocale(),{hour:'2-digit',minute:'2-digit',second:'2-digit'});const entry=latestCloudRun(kind);if(!entry)return t('Mai eseguito.');return new Date(entry.at).toLocaleString(appLocale())+' · '+cloudRunOutcomeText(entry.outcome)}
function syncCloudRunUi(){if($('cloudBackupStatus'))$('cloudBackupStatus').textContent=cloudRunStatusText('backup');if($('cloudSyncStatus'))$('cloudSyncStatus').textContent=cloudRunStatusText('sync');const connected=cloudConnected();if($('cloudRunBackupNow'))$('cloudRunBackupNow').disabled=!connected||cloudAutosaveBusy||!!cloudManualRunKind;if($('cloudRunSyncNow'))$('cloudRunSyncNow').disabled=!connected||cloudAutosaveBusy||cloudSyncBusy||!!cloudManualRunKind}
function setCloudRunProgress(kind,value=null){const wrap=$(kind==='backup'?'cloudBackupProgressWrap':'cloudSyncProgressWrap'),bar=$(kind==='backup'?'cloudBackupProgress':'cloudSyncProgress'),label=$(kind==='backup'?'cloudBackupProgressValue':'cloudSyncProgressValue');if(!wrap||!bar||!label)return;const active=value!==null;wrap.classList.toggle('hidden',!active);if(active){const percent=Math.max(0,Math.min(100,Number(value)||0));bar.value=percent;label.textContent=Math.round(percent)+'%'}}
function renderCloudRunLog(kind){cloudVisibleLogKind=kind;setLocalizedText($('cloudRunLogTitle'),kind==='backup'?'Log Automatic Backup':'Log Automatic Synch');const box=$('cloudRunLogList');box.replaceChildren();const entries=cloudRunLogs.filter(item=>item.kind===kind).slice(-100).reverse();if(!entries.length){const empty=document.createElement('p');empty.className='cloud-preview-empty';setLocalizedText(empty,'Nessuna operazione registrata.');box.append(empty);return}for(const entry of entries){const row=document.createElement('div');row.className='cloud-run-log-entry '+(entry.outcome==='success'?'success':entry.outcome==='failed'||entry.outcome==='conflict'?'error':'');const time=document.createElement('time');time.dateTime=new Date(entry.at).toISOString();time.textContent=new Date(entry.at).toLocaleString(appLocale());const content=document.createElement('div'),title=document.createElement('strong');title.textContent=cloudRunOutcomeText(entry.outcome);content.append(title);const source=document.createElement('span');source.className='help';source.textContent=t(entry.source==='manual'?'Avvio manuale':'Avvio automatico');content.append(source);if(entry.detail){const detail=document.createElement('div');detail.className='help';detail.textContent=entry.detail;content.append(detail)}row.append(time,content);box.append(row)}}
function openCloudRunLog(kind){renderCloudRunLog(kind);$('cloudRunLogDialog').showModal()}
function cloudAvailable({protocol=location.protocol,hostname=location.hostname,secure=globalThis.isSecureContext,subtle=globalThis.crypto?.subtle,Storage=mega?.Storage}={}){const loopback=['localhost','127.0.0.1','::1','[::1]'].includes(String(hostname||'').toLowerCase());return!!((protocol==='https:'||loopback)&&secure&&subtle&&Storage)}
function cloudConnected(){return cloudStorage?.status==='ready'&&!!cloudRoot}
function cloudStatus(message,error=false){const element=$('cloudStatus');if(element){setLocalizedText(element,message||'');element.classList.toggle('error',!!error)}}
function cloudExplorerStatus(message,error=false){const element=$('cloudExplorerStatus');if(element){setLocalizedText(element,message||'');element.classList.toggle('error',!!error)}}
function cloudFilePromise(method,...args){return new Promise((resolve,reject)=>{try{method(...args,(error,result)=>error?reject(error):resolve(result))}catch(error){reject(error)}})}
function cloudSecretDb(){return new Promise((resolve,reject)=>{const request=indexedDB.open(CLOUD_SECRET_DB,1);request.onupgradeneeded=()=>{if(!request.result.objectStoreNames.contains(CLOUD_SECRET_STORE))request.result.createObjectStore(CLOUD_SECRET_STORE)};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
async function cloudSecret(mode,key,value){const db=await cloudSecretDb();try{return await new Promise((resolve,reject)=>{const tx=db.transaction(CLOUD_SECRET_STORE,mode),store=tx.objectStore(CLOUD_SECRET_STORE),request=value===undefined?store.get(key):value===null?store.delete(key):store.put(value,key);tx.oncomplete=()=>resolve(request.result);tx.onerror=()=>reject(tx.error)})}finally{db.close()}}
async function saveCloudSession(){if(!cloudStorage)return;let key=await cloudSecret('readonly','key');if(!key){key=await crypto.subtle.generateKey({name:'AES-GCM',length:256},false,['encrypt','decrypt']);await cloudSecret('readwrite','key',key)}const iv=crypto.getRandomValues(new Uint8Array(12)),plain=new TextEncoder().encode(JSON.stringify(cloudStorage.toJSON())),cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,plain);await cloudSecret('readwrite','session',{version:1,iv:[...iv],cipher:[...new Uint8Array(cipher)]})}
async function clearCloudSession(){await cloudSecret('readwrite','session',null).catch(()=>{});await cloudSecret('readwrite','key',null).catch(()=>{})}
async function restoreCloudSession(){if(!cloudAvailable())return false;const record=await cloudSecret('readonly','session').catch(()=>null),key=await cloudSecret('readonly','key').catch(()=>null);if(!record||!key)return false;try{const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:new Uint8Array(record.iv)},key,new Uint8Array(record.cipher));cloudStorage=mega.Storage.fromJSON(JSON.parse(new TextDecoder().decode(plain)));cloudStorage.options.forceHttps=true;await cloudStorage.reload();cloudStorage.status='ready';await finishCloudConnection(false);return true}catch(error){console.warn('Sessione MEGA non ripristinata',error);await clearCloudSession();cloudStorage=null;return false}}
async function ensureCloudRoot(){cloudRoot=(cloudStorage.root.children||[]).find(node=>node.directory&&node.name===CLOUD_ROOT_NAME)||await cloudStorage.root.mkdir(CLOUD_ROOT_NAME);return cloudRoot}
async function ensureCloudFolder(parent,name){return(parent.children||[]).find(node=>node.directory&&node.name===name)||await parent.mkdir(name)}
async function finishCloudConnection(saveSession){await ensureCloudRoot();if(saveSession)await saveCloudSession();await refreshCloudQuota();cloudStartupSnapshot=await cloudCurrentManifest({discover:true}).catch(error=>{console.warn('Sessione Cloud non rilevata',error);return null});syncCloudUi();startCloudSyncWatcher();if(historyReady&&cloudStartupSnapshot)showCloudConflict(cloudStartupSnapshot,'available')}
async function cloudLogin(){if(!cloudAvailable())return;const button=$('cloudLoginBtn'),email=$('cloudEmail').value.trim(),password=$('cloudPassword').value,secondFactorCode=$('cloudUse2fa').checked?$('cloud2faCode').value.trim():'';if(!email||!password){cloudStatus('Inserisci email e password MEGA.',true);return}button.disabled=true;cloudStatus('Accesso a MEGA…');try{cloudStorage=new mega.Storage({email,password,secondFactorCode:secondFactorCode||undefined,forceHttps:true,keepalive:true});await cloudStorage.ready;$('cloudPassword').value='';$('cloud2faCode').value='';await finishCloudConnection($('cloudRememberSession').checked);cloudStatus('Cloud Storage collegato.')}catch(error){console.error(error);cloudStorage=null;cloudStatus('Accesso non riuscito: '+(error.message||error),true)}finally{button.disabled=false}}
async function cloudLogout(){stopCloudSyncWatcher();try{cloudStorage?.close?.()}catch(error){}cloudStorage=null;cloudRoot=null;cloudCurrent=null;await clearCloudSession();syncCloudUi();cloudStatus('Sessione MEGA rimossa da questo browser.')}
async function refreshCloudQuota(){if(!cloudStorage)return;const button=$('cloudQuotaRefresh');if(button)button.disabled=true;try{const info=await cloudStorage.getAccountInfo(),used=Number(info.spaceUsed)||0,total=Number(info.spaceTotal)||0,pct=total?Math.min(100,used/total*100):0;$('cloudQuotaValue').textContent=humanBytes(used)+' / '+humanBytes(total)+' · '+pct.toLocaleString(appLocale(),{maximumFractionDigits:1})+'%';$('cloudQuotaBar').style.width=pct+'%';$('cloudAccountName').textContent=cloudStorage.name||'MEGA';$('cloudAccountEmail').textContent=cloudStorage.email||''}catch(error){cloudStatus('Spazio MEGA non disponibile: '+error.message,true)}finally{if(button)button.disabled=false}}
function syncCloudUi(){const available=cloudAvailable(),connected=cloudConnected();$('cloudUnavailable')?.classList.toggle('hidden',available);$('cloudSignedOut')?.classList.toggle('hidden',!available||connected);$('cloudSignedIn')?.classList.toggle('hidden',!connected);for(const id of ['cloudAutomaticBackup','cloudAutomaticSync','cloudHideSyncBadge','cloudBrowseCopiesBtn'])if($(id))$(id).disabled=!connected;$('cloudCleanupBtn')&&($('cloudCleanupBtn').disabled=!connected);if($('cloudAutomaticBackup'))$('cloudAutomaticBackup').checked=!!preferences.cloudBackup;if($('cloudAutomaticSync'))$('cloudAutomaticSync').checked=!!preferences.cloudSync;if($('cloudHideSyncBadge'))$('cloudHideSyncBadge').checked=!!preferences.cloudHideSyncBadge;setLocalizedText($('cloudConnectionStatus'),connected?'Cloud Storage collegato.':'Cloud Storage non collegato.');syncCloudRunUi();syncCloudBadge()}
function nodeInsideCloud(node){for(let value=node;value;value=value.parent)if(value===cloudRoot)return true;return false}
function cloudCanWrite(){return cloudConnected()&&nodeInsideCloud(cloudCurrent)}
function cleanCloudName(value){const name=String(value||'').trim().replace(/[\\/:*?"<>|]/g,'_').slice(0,180);if(!name||name==='.'||name==='..')throw new Error(t('Nome non valido'));return name}
function uniqueCloudName(parent,base,suffix='Clone'){const names=new Set((parent.children||[]).map(node=>node.name.toLocaleLowerCase())),dot=base.lastIndexOf('.'),stem=dot>0?base.slice(0,dot):base,ext=dot>0?base.slice(dot):'';let name=stem+' ('+suffix+')'+ext,index=2;while(names.has(name.toLocaleLowerCase()))name=stem+' ('+suffix+' '+index+++')'+ext;return name}
function cloudMime(name){const extension=String(name).split('.').pop().toLowerCase();return{png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',webp:'image/webp',gif:'image/gif',svg:'image/svg+xml',pdf:'application/pdf',json:'application/json',zip:'application/zip'}[extension]||'application/octet-stream'}
function cloudNodeIcon(node){if(node.directory)return'📁';const type=cloudMime(node.name);return type.startsWith('image/')?'🖼️':type==='application/pdf'?'📄':type==='application/json'?'{}':'📎'}
function revokeCloudPreview(){cloudPreviewGeneration++;if(cloudPreviewUrl)URL.revokeObjectURL(cloudPreviewUrl);cloudPreviewUrl=''}
function renderCloudBreadcrumb(){const box=$('cloudBreadcrumb');box.replaceChildren();cloudPath.forEach((node,index)=>{const button=document.createElement('button');button.type='button';button.textContent=index===0?(node===cloudRoot?CLOUD_ROOT_NAME:t('Cloud Drive')):node.name;button.disabled=cloudExplorerMode==='save'&&index===0&&node===cloudRoot;button.onclick=()=>{cloudPath=cloudPath.slice(0,index+1);cloudCurrent=node;cloudSelection.clear();renderCloudExplorer()};box.append(button)});$('cloudBackBtn').disabled=cloudPath.length<=1}
function selectedCloudNodes(){return(cloudCurrent?.children||[]).filter(node=>cloudSelection.has(node.nodeId))}
function syncCloudToolbar(){const selected=selectedCloudNodes(),writable=cloudCanWrite();document.querySelectorAll('.cloud-write-action').forEach(button=>button.disabled=!writable);document.querySelectorAll('.cloud-selection-action').forEach(button=>button.disabled=!writable||!selected.length);$('cloudRenameBtn').disabled=!writable||selected.length!==1;$('cloudCloneBtn').disabled=!writable||selected.length!==1||selected[0]?.directory;$('cloudImportSelected').disabled=!selected.some(node=>!node.directory);$('cloudEditBtn').classList.toggle('active',cloudEditMode)}
function openCloudFolder(node){if(!node?.directory)return;revokeCloudPreview();cloudCurrent=node;cloudPath.push(node);cloudSelection.clear();renderCloudExplorer();$('cloudPreview').replaceChildren();const empty=document.createElement('div');empty.className='cloud-preview-empty';setLocalizedText(empty,'Seleziona un file per visualizzarne i dettagli.');$('cloudPreview').append(empty)}
async function previewCloudNode(node){
 revokeCloudPreview();const generation=cloudPreviewGeneration,box=$('cloudPreview');box.replaceChildren();
 const close=document.createElement('button');close.className='iconbtn cloud-preview-close';close.type='button';close.textContent='×';setLocalizedAttribute(close,'aria-label','Chiudi anteprima');setLocalizedAttribute(close,'data-tip','Chiudi anteprima');close.onclick=()=>{revokeCloudPreview();box.replaceChildren();const empty=document.createElement('div');empty.className='cloud-preview-empty';setLocalizedText(empty,'Seleziona un file per visualizzarne i dettagli.');box.append(empty)};
 const title=document.createElement('h3');title.textContent=node.name;const meta=document.createElement('p');meta.className='help cloud-preview-meta';const metaText=(node.directory?t('Cartella'):humanBytes(node.size))+(node.createdAt?' · '+new Date(node.createdAt).toLocaleString(appLocale()):'');meta.textContent=metaText;box.append(close,title,meta);
  if(node.directory){const actions=document.createElement('div');actions.className='cloud-preview-actions';const open=document.createElement('button');open.className='btn';open.type='button';setLocalizedText(open,'Apri');open.onclick=()=>openCloudFolder(node);actions.append(open);if(cloudCopyFolder(node)){const copies=document.createElement('button');copies.className='btn accent';copies.type='button';setLocalizedText(copies,'Esplora copie');copies.onclick=()=>{const scope=cloudCopyScopeFromNode(node);closeCloudExplorer();openCloudCopiesDialog(scope)};actions.append(copies)}box.append(actions);return}
 const type=cloudMime(node.name);
 if((type.startsWith('image/')&&node.size<=30*1024*1024)||(type==='application/pdf'&&node.size<=50*1024*1024)){
  const loading=document.createElement('p');setLocalizedText(loading,'Caricamento anteprima…');box.append(loading);
  try{const data=await node.downloadBuffer({forceHttps:true});if(generation!==cloudPreviewGeneration)return;const blob=new Blob([data],{type});cloudPreviewUrl=URL.createObjectURL(blob);loading.remove();
   if(type.startsWith('image/')){const image=document.createElement('img');image.className='cloud-image-preview';image.alt=node.name;image.onload=()=>{if(generation===cloudPreviewGeneration)meta.textContent=metaText+' · '+image.naturalWidth.toLocaleString(appLocale())+' × '+image.naturalHeight.toLocaleString(appLocale())+' px'};image.src=cloudPreviewUrl;box.append(image)}
   else{const frame=document.createElement('iframe');frame.className='cloud-pdf-preview';frame.src=cloudPreviewUrl;frame.title=node.name;box.append(frame)}
  }catch(error){if(generation!==cloudPreviewGeneration)return;loading.textContent=t('Anteprima non disponibile')+': '+(error.message||error)}
 }
 if(generation!==cloudPreviewGeneration)return;const actions=document.createElement('div');actions.className='cloud-preview-actions';const open=document.createElement('button');open.className='btn accent';open.type='button';setLocalizedText(open,'Apri in chicCanva');open.onclick=()=>importCloudNodes([node]);actions.append(open);box.append(actions)
}
function renderCloudExplorer(){if(!cloudSelection.size){revokeCloudPreview();const empty=document.createElement('div');empty.className='cloud-preview-empty';setLocalizedText(empty,'Seleziona un file per visualizzarne i dettagli.');$('cloudPreview').replaceChildren(empty)}renderCloudBreadcrumb();const box=$('cloudFileList');box.replaceChildren();const children=[...(cloudCurrent?.children||[])].sort((a,b)=>Number(b.directory)-Number(a.directory)||a.name.localeCompare(b.name,appLocale(),{sensitivity:'base'}));if(!children.length){const empty=document.createElement('div');empty.className='cloud-preview-empty';setLocalizedText(empty,'Questa cartella è vuota.');box.append(empty)}for(const node of children){const row=document.createElement('button');row.type='button';row.className='cloud-file-row'+(cloudSelection.has(node.nodeId)?' selected':'');row.dataset.nodeId=node.nodeId;row.setAttribute('role','option');row.setAttribute('aria-selected',String(cloudSelection.has(node.nodeId)));const icon=document.createElement('span');icon.className='cloud-file-icon';icon.textContent=cloudNodeIcon(node);const name=document.createElement('span');name.className='cloud-file-name';name.textContent=node.name;const meta=document.createElement('span');meta.className='cloud-file-meta';meta.textContent=node.directory?t('Cartella'):humanBytes(node.size);row.append(icon,name,meta);row.onclick=event=>{if(!cloudEditMode&&!event.ctrlKey&&!event.metaKey)cloudSelection.clear();cloudSelection.has(node.nodeId)?cloudSelection.delete(node.nodeId):cloudSelection.add(node.nodeId);renderCloudExplorer();previewCloudNode(node)};row.ondblclick=()=>{if(node.directory)openCloudFolder(node);else importCloudNodes([node])};box.append(row)}$('cloudConfirmSave').classList.toggle('hidden',cloudExplorerMode!=='save');$('cloudImportSelected').classList.toggle('hidden',cloudExplorerMode!=='browse');syncCloudToolbar()}
async function refreshCloudExplorer(){await cloudStorage.reload();cloudRoot=cloudStorage.root.find(CLOUD_ROOT_NAME)||await ensureCloudRoot();const ids=cloudPath.map(node=>node.nodeId);cloudPath=[cloudExplorerMode==='save'?cloudRoot:cloudStorage.root];for(const id of ids.slice(1)){const next=cloudPath.at(-1).children?.find(node=>node.nodeId===id);if(next)cloudPath.push(next)}cloudCurrent=cloudPath.at(-1);cloudSelection.clear();renderCloudExplorer();await refreshCloudQuota().catch(()=>{})}
function openCloudExplorer({mode='browse',artifact=null}={}){if(!cloudConnected()){toast(t('Accedi prima a MEGA'));return}cloudExplorerMode=mode;cloudPendingArtifact=artifact;cloudCurrent=mode==='save'?cloudRoot:cloudStorage.root;cloudPath=[cloudCurrent];cloudSelection.clear();cloudEditMode=false;setLocalizedText($('cloudExplorerTitle'),mode==='save'?'Salva su Cloud':'Cloud Storage');setLocalizedText($('cloudExplorerModeHelp'),mode==='save'?'Scegli una cartella dentro chicCanva Cloud.':'Fuori da chicCanva Cloud i file sono in sola lettura.');cloudExplorerStatus('');revokeCloudPreview();$('cloudPreview').innerHTML='<div class="cloud-preview-empty">'+t('Seleziona un file per visualizzarne i dettagli.')+'</div>';renderCloudExplorer();const tooltip=$('desktopTooltip');if(tooltip){cloudTooltipHome={parent:tooltip.parentNode,next:tooltip.nextSibling};$('cloudExplorerDialog').append(tooltip)}$('cloudExplorerDialog').showModal()}
function restoreCloudTooltip(){const tooltip=$('desktopTooltip');tooltip?.classList.add('hidden');if(tooltip&&cloudTooltipHome){const{parent,next}=cloudTooltipHome;parent?.insertBefore(tooltip,next?.parentNode===parent?next:null);cloudTooltipHome=null}}
function closeCloudExplorer(){restoreCloudTooltip();revokeCloudPreview();cloudPendingArtifact?.resolve?.(false);cloudPendingArtifact=null;if($('cloudExplorerDialog').open)$('cloudExplorerDialog').close()}
function askCloudText(title,label,value=''){return new Promise(resolve=>{cloudTextResolver=resolve;setLocalizedText($('cloudTextTitle'),title);setLocalizedText($('cloudTextLabel').firstChild,label);$('cloudTextInput').value=value;$('cloudTextDialog').showModal();setTimeout(()=>$('cloudTextInput').focus(),0)})}
function finishCloudText(value=null){if($('cloudTextDialog').open)$('cloudTextDialog').close();const resolve=cloudTextResolver;cloudTextResolver=null;resolve?.(value)}
function askCloudConfirm(title,message){return new Promise(resolve=>{cloudConfirmResolver=resolve;setLocalizedText($('cloudConfirmTitle'),title);setLocalizedText($('cloudConfirmMessage'),message);$('cloudConfirmDialog').showModal()})}
function finishCloudConfirm(value=false){if($('cloudConfirmDialog').open)$('cloudConfirmDialog').close();const resolve=cloudConfirmResolver;cloudConfirmResolver=null;resolve?.(value)}
function chooseCloudDeleteMode(message){return new Promise(resolve=>{cloudDeleteModeResolver=resolve;setLocalizedText($('cloudDeleteModeMessage'),message);$('cloudDeleteModeDialog').showModal()})}
function finishCloudDeleteMode(value='cancel'){if($('cloudDeleteModeDialog').open)$('cloudDeleteModeDialog').close();const resolve=cloudDeleteModeResolver;cloudDeleteModeResolver=null;resolve?.(value)}
function deleteCloudNode(node,mode='trash'){return node.delete(mode==='permanent')}
async function uploadCloudBlob(folder,name,blob,progress=true,replacePermanent=true){name=cleanCloudName(name);const existing=(folder.children||[]).find(node=>!node.directory&&node.name===name);const upload=folder.upload({name,size:blob.size,forceHttps:true},new Uint8Array(await blob.arrayBuffer()));upload.on?.('progress',event=>{const pct=event.bytesTotal?event.bytesUploaded/event.bytesTotal*100:0;if(progress){$('cloudProgressBar').value=pct;$('cloudProgressValue').textContent=Math.round(pct)+'%'}if(cloudActiveRunKind)setCloudRunProgress(cloudActiveRunKind,pct)});if(progress){$('cloudProgress').classList.remove('hidden');setLocalizedText($('cloudProgressLabel'),'Caricamento '+name+'…')}const node=await upload.complete;if(cloudActiveRunKind)setCloudRunProgress(cloudActiveRunKind,100);if(existing)await existing.delete(replacePermanent);if(progress)$('cloudProgress').classList.add('hidden');return node}
async function importCloudNodes(nodes=selectedCloudNodes()){const queue=[];for(const node of nodes.filter(item=>!item.directory)){cloudExplorerStatus('Download '+node.name+'…');const data=await node.downloadBuffer({forceHttps:true}),file=new File([data],node.name,{type:cloudMime(node.name),lastModified:node.createdAt||Date.now()}),item={file,kind:classifyIncomingFile(file)};await inspectIncomingItem(item);queue.push(item)}closeCloudExplorer();if(queue.length){incomingShareQueue.push(...queue);await showNextIncomingShare()}}
function chooseCloudDestination(description){if(!cloudConnected())return Promise.resolve('device');return new Promise(resolve=>{cloudDestinationResolver=resolve;$('cloudDestinationInfo').textContent=t(description||'Scegli dove salvare il file.');$('cloudDestinationDialog').showModal()})}
function finishCloudDestination(value){if($('cloudDestinationDialog').open)$('cloudDestinationDialog').close();const resolve=cloudDestinationResolver;cloudDestinationResolver=null;resolve?.(value)}
async function deliverCloudArtifact(artifact,onSuccess){const destination=await chooseCloudDestination(artifact.description);if(destination==='cancel')return false;if(destination==='device')download(artifact.fileName,artifact.blob);else await new Promise(resolve=>{openCloudExplorer({mode:'save',artifact:{...artifact,onSuccess,resolve}})});if(destination==='device')onSuccess?.();return true}
async function runCloudUnifiedExport(){const button=$('exportPdfPanel'),status=$('projectStatus'),label=button.textContent;button.disabled=true;try{const destination=await chooseCloudDestination('Il file verrà generato dopo la scelta della destinazione.');if(destination==='cancel')return;const artifact=await buildUnifiedExportArtifact(message=>status.textContent=message);if(destination==='device')download(artifact.fileName,artifact.blob);else await new Promise(resolve=>openCloudExplorer({mode:'save',artifact:{...artifact,resolve}}));status.textContent=artifact.description}catch(error){console.error(error);status.textContent=t('Esportazione non riuscita: ')+(error.message||error)}finally{button.disabled=false;button.textContent=label}}
